            addStaticVar(vcg);


        }
        addLineNumberInfo(v);
        debug("forVarRef ", v , " Value = ", vcg);
        String static_args = NamingCzar.instantiatedGenericDecoration(lsargs, thisApi());
        vcg.pushValue(mv, static_args);
    }

